"""Append the source-checked peer-review evaluation; never alter raw inputs.
Run once for the report append; --validate rechecks quotes and required sections.
No git probes: the operator prohibits every git command.
"""
from pathlib import Path
import json, re, sys

ROOT = Path('data/derived/akbari_peer_review')
DOC = Path('docs/akbari-peer-review-evaluation.md')
pages = {p['page']: p['text'] for p in json.loads((ROOT/'pages.json').read_text())}
def norm(s):
    return re.sub(r'\s+', ' ', s).strip()
ledger = []
def q(page, version, speaker, text):
    text = norm(text)
    assert text in norm(pages[page]), (page, text)
    ledger.append(dict(page=page, version=version, speaker=speaker, quote=text))
    rendered = text.replace('|', r'\|')
    return f'“{rendered}” ({version}, {speaker}, PDF p. {page})'
rows=[]
def row(v,r,cp,c,ap,a,status,assessment):
    cq=q(cp,v,f'R{r}',c)
    aq=q(ap,v+' response','authors',a) if ap else 'no direct response'
    rows.append(f'| {len(rows)+1} | {v} | R{r} | {cq} | {aq} | [observation] {status} | [inference] {assessment} |')

